    detail=True,
    permission_classes=[PaperlessNotePermissions],
    pagination_class=None,
    filter_backends=[],
)
def notes(self, request, pk=None):

try:
    doc = (
        Document.objects.select_related("owner")
        .prefetch_related("notes")
        .only("pk", "owner__id")
        .get(pk=pk)
    )
    if currentUser is not None and not has_perms_owner_aware(
        currentUser,
        "view_document",
        doc,
    ):
        return HttpResponseForbidden("Insufficient permissions to view notes")
except Document.DoesNotExist:
    raise Http404

elif request.method == "POST":
    try:
        if currentUser is not None and not has_perms_owner_aware(
            currentUser,
            "change_document",
            doc,
        ):
            return HttpResponseForbidden(
                "Insufficient permissions to create notes",
            )

class PaperlessNotePermissions(BasePermission):
    """
    Permissions class that checks for model permissions for Notes.
    """

    perms_map = {
        "OPTIONS": ["documents.view_note", "documents.view_document"],
        "GET": ["documents.view_note", "documents.view_document"],
        "POST": [
            "documents.add_note",
            "documents.view_document",
            "documents.change_document",
        ],
        "DELETE": [
            "documents.delete_note",
            "documents.view_document",
            "documents.change_document",
        ],
    }

    def has_permission(self, request, view):
        if not request.user or (not request.user.is_authenticated):  # pragma: no cover
            return False

        perms = self.perms_map[request.method]

        return request.user.has_perms(perms)

if currentUser is not None and not has_perms_owner_aware(
    currentUser,
    "view_document",
    doc,
):
    return HttpResponseForbidden("Insufficient permissions to view notes")

elif request.method == "POST":
    try:
        if currentUser is not None and not has_perms_owner_aware(
            currentUser,
            "change_document",
            doc,
        ):
            return HttpResponseForbidden(
                "Insufficient permissions to create notes",
            )

        c = Note.objects.create(
            document=doc,
            note=request.data["note"],
            user=currentUser,
        )
